		'dates.early_hours' => array(
			'en' => 'Starting October 19, permanent early voting sites must be open weekdays 8:30 a.m. to 4:30 p.m. or 9 a.m. to 5 p.m., and until 7 p.m. on weekdays in the last 8 days. Saturdays and holidays: 9 a.m. to noon. Sundays: 10 a.m. to 4 p.m. Temporary sites set their own hours.',
			'es' => 'A partir del 19 de octubre, los centros permanentes de votación anticipada deben abrir entre semana de 8:30 a. m. a 4:30 p. m. o de 9 a. m. a 5 p. m., y hasta las 7 p. m. entre semana en los últimos 8 días. Sábados y días festivos: de 9 a. m. al mediodía. Domingos: de 10 a. m. a 4 p. m. Los lugares temporales fijan su propio horario.',
			'src' => 'https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=001000050K19A-15',
			'checked' => '2026-10-21',
		),
		'dates.cure' => array(
			'en' => 'If your mail ballot is rejected, your election authority must send you a notice within two days. You can show why it should count until Tuesday, November 17, 2026.',
			'es' => 'Si rechazan tu boleta por correo, tu autoridad electoral debe enviarte un aviso en un plazo de dos días. Tienes hasta el martes 17 de noviembre de 2026 para demostrar por qué debe contarse.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9OQfN8tD1KknCt4vGDLyf%2beCKsyu7xmW0lAxDBpXvp%2bNIr4wjxV9GPBgF6J94lGLth4owFgdUkow%3d',
			'checked' => '2026-10-21',
		),
		'how.in_person' => array(
			'en' => 'Vote early at any early voting site your election authority sets up. On Election Day, go to your polling place between 6 a.m. and 7 p.m. Every election authority also runs at least one Election Day vote center where any voter in its area can vote.',
			'es' => 'Vota por anticipado en cualquier lugar de votación anticipada que abra tu autoridad electoral. El Día de las Elecciones, ve a tu lugar de votación entre las 6 a. m. y las 7 p. m. Cada autoridad electoral también tiene por lo menos un centro de votación el Día de las Elecciones donde puede votar cualquier votante de su zona.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9OQfN8tD1KknCt4vGDLyf%2beCKsyu7xmW0lAxDBpXvp%2bNIr4wjxV9GPBgF6J94lGLth4owFgdUkow%3d',
			'checked' => '2026-10-21',
		),
		'how.first_time' => array(
			'en' => 'Registering during the grace period? Bring two forms of ID, at least one with your current address, like a driver\'s license, lease, utility bill or bank statement. You vote right then, in person, at the same visit.',
			'es' => '¿Te vas a registrar durante el periodo de gracia? Lleva dos identificaciones, por lo menos una con tu dirección actual, como una licencia de conducir, un contrato de renta, un recibo de servicios o un estado de cuenta bancario. Votas ahí mismo, en persona, en la misma visita.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9OAgI8oxP06UUz3N9a%2babH2TsAY3ULa94pWnj7HwRoALh1dif5CSlCA%3d%3d',
