		'id.rule' => 'no_id',
		'mail.who' => array(
			'en' => 'Any registered voter can vote by mail, no excuse needed. You can also ask to join the permanent vote by mail list and get a ballot for every election.',
			'es' => 'Cualquier votante registrado puede votar por correo, sin dar una razón. También puedes pedir que te pongan en la lista permanente de voto por correo y recibir una boleta en cada elección.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGlSMHdiy2iXFAjyfyuQAf7RuSHGhmj4krBXKBjMHMC1kXG9lGcteFHxJG77yV2o99NE75AqeL5DThKkCHpaEu2oLSuh20w3EwQdWH71Ci9K32uwKewIazRSajZGQBVzmfzwlOzw4whnSWC4%2fbXhBNlQ%3d%3d',
			'checked' => '2026-10-21',
		),
		'mail.cure' => array(
			'en' => 'If your signature is missing or doesn\'t match, you\'ll get a notice by mail within two days with steps to get your ballot reinstated. You have 14 days after the election to fix it with your election authority.',
			'es' => 'Si falta tu firma o no coincide, recibirás un aviso por correo en un plazo de dos días con los pasos para que tu boleta vuelva a ser válida. Tienes 14 días después de la elección para corregirlo con tu autoridad electoral.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGlSMHdiy2iXFAjyfyuQAf7RuSHGhmj4krBXKBjMHMC1kXG9lGcteFHxJG77yV2o99NE75AqeL5DThKkCHpaEu2oLSuh20w3EwQdWH71Ci9K32uwKewIazRSajZGQBVzmfzwlOzw4whnSWC4%2fbXhBNlQ%3d%3d',
