		'mail.dropbox' => array(
			'en' => 'Some election authorities have drop boxes, open until 7 p.m. on Election Day, no stamp needed. Check the State Board of Elections\' drop box list. You can also hand it in at your election authority\'s office.',
			'es' => 'Algunas autoridades electorales tienen buzones de entrega, abiertos hasta las 7 p. m. del Día de las Elecciones, sin estampilla. Revisa la lista de buzones de la Junta Electoral del Estado. También puedes entregarla en la oficina de tu autoridad electoral.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGlSMHdiy2iXFAjyfyuQAf7RuSHGhmj4krBXKBjMHMC1kXG9lGcteFHxJG77yV2o99NE75AqeL5DThKkCHpaEu2oLSuh20w3EwQdWH71Ci9K32uwKewIazRSajZGQBVzmfzwlOzw4whnSWC4%2fbXhBNlQ%3d%3d',
