		'mail.witness' => array(
			'en' => 'Sign the certification on the ballot envelope. If someone helps you mark your ballot, their name and address go on the envelope too.',
			'es' => 'Firma la certificación en el sobre de la boleta. Si alguien te ayuda a marcar tu boleta, su nombre y dirección también van en el sobre.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ993sRKyHy6NSrOeqhGSgJZjOQiDLWY39IoNmqSBb0J5o%3d',
