		'polls_rules.gear' => array(
			'en' => 'Look for cones or small flags about 100 feet from the entrance. Inside that line is a campaign-free zone: no one may campaign or ask for votes. The same zone applies at early voting sites.',
			'es' => 'Busca conos o banderitas a unos 100 pies de la entrada. Dentro de esa línea hay una zona libre de campaña: nadie puede hacer campaña ni pedir votos. La misma zona aplica en los lugares de votación anticipada.',
			'src' => 'https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=001000050K17-29',
			'checked' => '2026-10-21',
		),
		'faq.provisional' => array(
			'en' => 'You vote a provisional ballot if, for example, your name isn\'t on the precinct list, your eligibility is challenged, or you registered by mail without ID and still can\'t show it. You can bring more proof to your election authority by close of business on the Tuesday after the election, November 10. The election authority decides within 14 days whether it counts.',
			'es' => 'Votas con una boleta provisional si, por ejemplo, tu nombre no aparece en la lista del precinto, cuestionan tu derecho a votar o te registraste por correo sin identificación y todavía no puedes mostrarla. Puedes llevar más pruebas a tu autoridad electoral a más tardar al cierre del día hábil del martes después de la elección, el 10 de noviembre. La autoridad electoral decide en un plazo de 14 días si se cuenta.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9wLcsNnM%2fXIuUHd1t%2b364AGqaMSnCpJ4Q%2bBr6S8vrv9k2jo5dDGVArA%3d%3d',
			'checked' => '2026-10-21',
		),
		'faq.unsigned' => array(
			'en' => 'Your election authority will mail you a notice within two days with steps to fix it. You have until Tuesday, November 17, 2026 to resolve it, so check your mail after you send your ballot back.',
			'es' => 'Tu autoridad electoral te enviará un aviso por correo en un plazo de dos días con los pasos para corregirlo. Tienes hasta el martes 17 de noviembre de 2026 para resolverlo, así que revisa tu correo después de devolver tu boleta.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9OQfN8tD1KknCt4vGDLyf%2beCKsyu7xmW0lAxDBpXvp%2bNIr4wjxV9GPBgF6J94lGLth4owFgdUkow%3d',
			'checked' => '2026-10-21',
		),
		'faq.late_mail' => array(
			'en' => 'A postmark isn\'t guaranteed the day you mail it. Close to Election Day, ask at the post office counter for a hand postmark, or use a drop box or your election authority\'s office instead.',
			'es' => 'El matasellos no está garantizado el mismo día que la envías. Cerca del Día de las Elecciones, pide en el mostrador de la oficina postal que le pongan el matasellos a mano, o mejor usa un buzón de entrega o la oficina de tu autoridad electoral.',
			'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ993sRKyHy6NSrOeqhGSgJZjOQiDLWY39IoNmqSBb0J5o%3d',
